/*
 * NOVA_ATELIER — Kinetic 3D Type Headline (revision 1)
 * 1) COMPOSITION: graded + LIT backdrop plane (7x5.5 @ z=-1.5) receiving the split-contrast
 *    rig so warm/red light pools break the flat void; caption kicker (y=1.15) / hero
 *    "TIME, MACHINED." split into two words with z offsets (0.12 / 0.0) at y=0.4 /
 *    accent underline rule (y=-0.05) / subhead (y=-0.65) / two foreground machined
 *    calibration tick-marks (z=0.3) give a third depth plane at the lower frame edge.
 * 2) LIGHT RIG: rig-split-contrast — key spot #f6f2ec@55 from [2.9,1.5,0.4], kicker spot
 *    #ff2a38@48 from [-2.9,1.5,0.4] (both aimed at [0,0.5,0]), rim directional #fff@1.1
 *    from [0,2.6,-2.6] aimed at [0,0.6,0], plus a 0.06 ambient floor — the backdrop is now
 *    a lit MeshStandardNodeMaterial so this rig actually shapes the stage.
 * 3) MATERIALS: backdrop = MeshStandardNodeMaterial (roughness 0.92, metalness 0) with a
 *    TSL vertical gradient + grain + vignette colorNode, lit by the rig; accent underline
 *    and tick-marks = MeshStandardNodeMaterial roughness 0.55 metalness 0.2 emissive
 *    #ff2a38 (proper THREE.Color instance, intensity 1.2); text rendered exclusively via
 *    ctx.fontAtlas (MSDF), fitted to spec em-heights via bbox scaling.
 * 4) MOTION: ctx.primitives['kinetic-text'] on load drives the primitive's own hook, plus a
 *    guaranteed manual timeline: per-word position rise AND opacity fade (0->1, the
 *    previous build left opacity stuck at 0 — fixed here), a weighted-settle scale
 *    overshoot on the hero group, underline scaleX reveal, and subhead/caption fade-ups.
 * 5) FOCAL ELEMENT: the hero headline "TIME, MACHINED." — brightest, largest, frontmost,
 *    now guaranteed visible (opacity bug fixed) and the only element crossing 0.5 em scale.
 */

import {
  Group,
  Mesh,
  PlaneGeometry,
  SpotLight,
  DirectionalLight,
  AmbientLight,
  Object3D,
  Box3,
  Color,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  color,
  mix,
  smoothstep,
  vec2,
  dot,
  sin,
  fract,
  length,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#101017',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  gradTop: '#13131a',
  gradBottom: '#0b0b10',
};

function fitTextHeight(obj, targetHeight) {
  const box = new Box3().setFromObject(obj);
  const h = box.max.y - box.min.y;
  if (h > 0.0001) {
    const s = targetHeight / h;
    obj.scale.setScalar(s);
  }
  return obj;
}

function textWidth(obj) {
  const box = new Box3().setFromObject(obj);
  return box.max.x - box.min.x;
}

// collect every unique material on an Object3D (fontAtlas text may be a Group of glyphs)
function getMaterials(obj) {
  const set = new Set();
  obj.traverse((child) => {
    if (child.isMesh && child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => m && set.add(m));
    }
  });
  return Array.from(set);
}

function setOpacity(obj, value) {
  const mats = getMaterials(obj);
  mats.forEach((m) => {
    m.transparent = true;
    m.opacity = value;
    m.needsUpdate = true;
  });
  return mats;
}

// --- section: buildBackdrop (color.background, color.surface, color.gradient) ---
function buildBackdrop() {
  const geo = new PlaneGeometry(7, 5.5, 1, 1);
  // lit standard material so the split-contrast rig actually shapes the stage
  // (an unlit basic material leaves the backdrop flat/dead regardless of lights)
  const mat = new MeshStandardNodeMaterial({ roughness: 0.92, metalness: 0.0 });

  const gUv = uv();
  const top = color(COLORS.gradTop);
  const bottom = color(COLORS.gradBottom);
  const gradient = mix(bottom, top, smoothstep(0.0, 1.0, gUv.y));

  // mono grain, 1.5%
  const seed = dot(gUv, vec2(12.9898, 78.233));
  const grain = fract(sin(seed).mul(43758.5453));
  const grainAmt = grain.mul(0.015).sub(0.0075);

  // subtle vignette toward frame edges so the center (hero) reads brighter/focused
  const centered = gUv.sub(vec2(0.5, 0.5));
  const dist = length(centered);
  const vignette = clamp(dist.mul(0.35), 0.0, 0.12);

  mat.colorNode = gradient.add(grainAmt).sub(vignette);

  const mesh = new Mesh(geo, mat);
  mesh.position.set(0, 0, -1.5);
  mesh.name = 'backdrop';
  return mesh;
}

// --- section: buildLights ---
function buildLights(group) {
  const disposables = [];

  const ambient = new AmbientLight(0xffffff, 0.06);
  group.add(ambient);

  const key = new SpotLight(0xf6f2ec, 55, 0, 0.5, 0.4, 1.0);
  key.position.set(2.9, 1.5, 0.4);
  const keyTarget = new Object3D();
  keyTarget.position.set(0, 0.5, 0);
  group.add(keyTarget);
  key.target = keyTarget;
  group.add(key);

  const kicker = new SpotLight(0xff2a38, 48, 0, 0.5, 0.4, 1.0);
  kicker.position.set(-2.9, 1.5, 0.4);
  const kickerTarget = new Object3D();
  kickerTarget.position.set(0, 0.5, 0);
  group.add(kickerTarget);
  kicker.target = kickerTarget;
  group.add(kicker);

  const rim = new DirectionalLight(0xffffff, 1.1);
  rim.position.set(0, 2.6, -2.6);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0.6, 0);
  group.add(rimTarget);
  rim.target = rimTarget;
  group.add(rim);

  disposables.push(ambient, key, kicker, rim, keyTarget, kickerTarget, rimTarget);
  return disposables;
}

// --- section: buildCaption (text.caption.0) ---
function buildCaption(ctx, captionStr) {
  const t = ctx.fontAtlas.createText(captionStr, {
    fontSize: 18,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 2.2,
  });
  fitTextHeight(t, 0.09);
  t.position.set(0, 1.15, 0);
  t.name = 'caption';
  return t;
}

// --- section: buildHero (text.hero.1, effects.spec, primitive.kinetic-text) ---
function buildHero(ctx, heroStr) {
  const words = heroStr.split(' ');
  const zOffsets = [0.12, 0.0, -0.12];
  const heroGroup = new Group();
  heroGroup.name = 'hero-group';

  const wordObjs = words.map((w, i) => {
    const wo = ctx.fontAtlas.createText(w, {
      fontSize: 124,
      color: COLORS.paper,
      align: 'center',
      letterSpacingPx: -1.24,
    });
    fitTextHeight(wo, 0.62);
    wo.userData.z = zOffsets[i] ?? 0;
    return wo;
  });

  const gap = 0.14;
  const widths = wordObjs.map((w) => textWidth(w));
  const totalWidth = widths.reduce((a, b) => a + b, 0) + gap * (wordObjs.length - 1);
  let cursor = -totalWidth / 2;
  wordObjs.forEach((wo, i) => {
    const w = widths[i];
    wo.position.set(cursor + w / 2, 0, wo.userData.z);
    heroGroup.add(wo);
    cursor += w + gap;
  });

  heroGroup.position.set(0, 0.4, 0);
  return { heroGroup, wordObjs, wordCount: words.length };
}

// --- section: buildSubhead (text.subhead.2) ---
function buildSubhead(ctx, subheadStr) {
  const s = ctx.fontAtlas.createText(subheadStr, {
    fontSize: 40,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 0.8,
  });
  fitTextHeight(s, 0.2);
  s.position.set(0, -0.65, 0);
  s.name = 'subhead';
  return s;
}

// --- section: buildAccentUnderline (color.accent) ---
function buildAccentUnderline() {
  const width = 2.6;
  const height = 0.045;
  const geo = new PlaneGeometry(width, height, 1, 1);
  geo.translate(width / 2, 0, 0); // pivot at left edge for anchor-left scale

  const mat = new MeshStandardNodeMaterial({
    color: COLORS.accent,
    roughness: 0.55,
    metalness: 0.2,
  });
  mat.emissive = new Color(COLORS.accent); // must be a Color instance, not a TSL node
  mat.emissiveIntensity = 1.2;

  const pivot = new Group();
  pivot.name = 'accent-underline-pivot';
  const mesh = new Mesh(geo, mat);
  mesh.position.set(0, 0, 0.01);
  pivot.add(mesh);

  pivot.position.set(-width / 2, -0.05, 0);
  pivot.scale.x = 0.0001;

  return { pivot, mesh, geo, mat };
}

// --- section: buildForegroundTicks (composition depth-plane #3, color.accent, machined motif) ---
function buildForegroundTicks() {
  const geo = new PlaneGeometry(0.4, 0.03, 1, 1);
  const mat = new MeshStandardNodeMaterial({
    color: COLORS.accent,
    roughness: 0.5,
    metalness: 0.25,
  });
  mat.emissive = new Color(COLORS.accent);
  mat.emissiveIntensity = 0.8;

  const left = new Mesh(geo, mat);
  left.position.set(-3.0, -2.35, 0.3);
  left.name = 'tick-left';

  const right = new Mesh(geo, mat);
  right.position.set(3.0, -2.35, 0.3);
  right.name = 'tick-right';

  return { left, right, geo, mat };
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'nova-kinetic-headline';

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const captionItem = items.find((i) => i.role === 'caption');
  const heroItem = items.find((i) => i.role === 'hero');
  const subheadItem = items.find((i) => i.role === 'subhead');

  const captionStr = (captionItem?.text ?? 'NOVA ATELIER / CALIBRE PROGRAM').toUpperCase();
  const heroStr = heroItem?.text ?? 'TIME, MACHINED.';
  const subheadStr = subheadItem?.text ?? 'Every calibre begins as a solid billet.';

  // --- section: backdrop (color.background/surface/gradient) ---
  const backdrop = buildBackdrop();
  group.add(backdrop);

  // --- section: lights ---
  const lightObjs = buildLights(group);

  // --- section: foreground depth plane (composition law: 3 depth planes minimum) ---
  const { left: tickLeft, right: tickRight, geo: tickGeo, mat: tickMat } = buildForegroundTicks();
  group.add(tickLeft, tickRight);

  // --- section: caption ---
  const captionText = buildCaption(ctx, captionStr);
  group.add(captionText);

  // --- section: hero ---
  const { heroGroup, wordObjs, wordCount } = buildHero(ctx, heroStr);
  group.add(heroGroup);

  // --- section: subhead ---
  const subheadText = buildSubhead(ctx, subheadStr);
  group.add(subheadText);

  // --- section: accent underline ---
  const { pivot: underlinePivot, mesh: underlineMesh, geo: underlineGeo, mat: underlineMat } =
    buildAccentUnderline();
  group.add(underlinePivot);

  const timelines = [];
  let primitiveHandle = null;

  // --- section: applyKineticText (primitive.kinetic-text) ---
  const kineticCfg = (config.cinematicPrimitives || []).find(
    (p) => p.name === 'kinetic-text'
  );
  const staggerMs = kineticCfg?.params?.staggerMs ?? 60;
  const riseUnits = kineticCfg?.params?.riseUnits ?? 0.35;

  // initial hidden state: per-word rise offset AND opacity 0 (fixes prior invisible-hero bug)
  const wordMaterials = wordObjs.map((wo) => {
    wo.position.y += riseUnits;
    return setOpacity(wo, 0);
  });

  try {
    primitiveHandle = ctx.primitives['kinetic-text'](heroGroup, {
      staggerMs,
      riseUnits,
      trigger: 'load',
    });
  } catch (e) {
    primitiveHandle = null;
  }

  // manual timeline guarantees spec timing regardless of primitive internals:
  // rise + fade per word, weighted-settle, underline reveal, subhead/caption fade-up.
  const glyphDuration = 0.7; // 700ms
  const staggerSec = staggerMs / 1000;
  const totalStagger = staggerSec * Math.max(wordCount - 1, 0);
  const kineticEnd = totalStagger + glyphDuration;

  const tlEntrance = gsap.timeline();
  wordObjs.forEach((wo, i) => {
    const startAt = i * staggerSec;
    tlEntrance.to(
      wo.position,
      {
        y: wo.position.y - riseUnits,
        duration: glyphDuration,
        ease: 'power3.out',
      },
      startAt
    );
    tlEntrance.to(
      wordMaterials[i],
      {
        opacity: 1,
        duration: glyphDuration,
        ease: 'power2.out',
      },
      startAt
    );
  });
  timelines.push(tlEntrance);

  const tlSettle = gsap.timeline({ delay: kineticEnd });
  tlSettle.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(tlSettle);

  const tlUnderline = gsap.timeline({ delay: kineticEnd + 0.12 });
  tlUnderline.to(underlinePivot.scale, {
    x: 1.0,
    duration: 0.5,
    ease: 'power2.out',
  });
  timelines.push(tlUnderline);

  // subhead fade-up: opacity 0->1 + y +0.2 -> 0
  const subheadMats = setOpacity(subheadText, 0);
  const subheadBaseY = subheadText.position.y;
  subheadText.position.y = subheadBaseY + 0.2;
  const tlSubhead = gsap.timeline({ delay: 0.1 });
  tlSubhead.to(subheadText.position, {
    y: subheadBaseY,
    duration: 0.5,
    ease: 'power2.out',
  });
  tlSubhead.to(
    subheadMats,
    { opacity: 1, duration: 0.5, ease: 'power2.out' },
    0
  );
  timelines.push(tlSubhead);

  // caption fade-up: opacity 0->1 + y +0.15 -> 0
  const captionMats = setOpacity(captionText, 0);
  const captionBaseY = captionText.position.y;
  captionText.position.y = captionBaseY + 0.15;
  const tlCaption = gsap.timeline({ delay: 0 });
  tlCaption.to(captionText.position, {
    y: captionBaseY,
    duration: 0.5,
    ease: 'power2.out',
  });
  tlCaption.to(
    captionMats,
    { opacity: 1, duration: 0.5, ease: 'power2.out' },
    0
  );
  timelines.push(tlCaption);

  // foreground ticks: subtle settle-in, echoing the underline reveal
  tickLeft.scale.set(0.0001, 1, 1);
  tickRight.scale.set(0.0001, 1, 1);
  const tlTicks = gsap.timeline({ delay: kineticEnd + 0.2 });
  tlTicks.to([tickLeft.scale, tickRight.scale], {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
  });
  timelines.push(tlTicks);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (primitiveHandle && typeof primitiveHandle.cleanup === 'function') {
      primitiveHandle.cleanup();
    }
    lightObjs.forEach((l) => {
      if (l.dispose) l.dispose();
    });

    backdrop.geometry?.dispose();
    backdrop.material?.dispose();

    underlineGeo.dispose();
    underlineMat.dispose();

    tickGeo.dispose();
    tickMat.dispose();

    group.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach((m) => {
          if (!m) return;
          if (m.map) m.map.dispose?.();
          m.dispose?.();
        });
      }
    });
  };

  return group;
}

/* @spec-manifest
{"elements":[
  {"id":"text.caption.0","where":"buildCaption","how":"ctx.fontAtlas.createText caption string, fitted 0.09 em"},
  {"id":"text.hero.1","where":"buildHero","how":"per-word MSDF text, z offsets, 0.62 em, opacity fade fixed"},
  {"id":"text.subhead.2","where":"buildSubhead","how":"ctx.fontAtlas.createText subhead, fitted 0.2 em"},
  {"id":"color.background","where":"buildBackdrop","how":"gradBottom #0b0b10 in TSL gradient node"},
  {"id":"color.surface","where":"COLORS.surface","how":"defined in COLORS constant for material use"},
  {"id":"color.ink","where":"COLORS.ink","how":"defined in COLORS constant for material use"},
  {"id":"color.paper","where":"buildCaption/buildHero/buildSubhead","how":"text color set to #e8ecf2"},
  {"id":"color.accent","where":"buildAccentUnderline/buildForegroundTicks","how":"underline+tick meshes color+emissive #ff2a38"},
  {"id":"color.gradient","where":"buildBackdrop","how":"mix(bottom,top,smoothstep(uv.y)) TSL gradient + vignette"},
  {"id":"effects.spec","where":"buildHero+createNode entrance timelines","how":"per-word rise/fade, weighted-settle, underline reveal, grain, lit backdrop"},
  {"id":"primitive.kinetic-text","where":"createNode applyKineticText section","how":"ctx.primitives['kinetic-text'](heroGroup,{staggerMs,riseUnits})"}
]}
*/
